// Package volt is the runtime for code generated by the volt CLI: the
// request and response values, the shim that performs a handler's
// effects and writes its response, the error spine, the reverse-URL
// building blocks, the route-table types, and a minimal middleware set.
// It imports the standard library and the data runtime nao/rt alone
// (spec §data-and-network-layers) and never holds a database: the
// generated router hands the shim a Performer.
package volt

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"time"

	"github.com/Piechutowski/volt/nao/rt"
)

// HandlerFunc is a handler after parameter binding: a function from
// the request value to a response value (spec §requests-and-responses).
type HandlerFunc func(Request) Response

// ErrorHandler chooses the response for a failure (spec §scopes): a
// handler's Fail, a failed effect, an unparseable body. It returns a
// done response; DefaultErrorHandler is the one routes without an
// error_handler use.
type ErrorHandler func(Request, error) Response

// HandlerOption configures a shim: Params names the path parameters the
// request value reads, Timeout bounds the whole chain (§route-loads).
type HandlerOption func(*shim)

type shim struct {
	params  []string
	timeout time.Duration
}

// Params names the route's path parameters, read once into the request
// value.
func Params(names ...string) HandlerOption {
	return func(s *shim) { s.params = append(s.params, names...) }
}

// Timeout bounds the handler and every effect it describes with one
// deadline from the request's arrival (spec §route-loads); an effect the
// deadline cuts off is a 504 through the error handler.
func Timeout(d time.Duration) HandlerOption {
	return func(s *shim) { s.timeout = d }
}

// Handler is the shim: it builds the request value, calls h, performs
// every continuation through perform, hands failures to eh and writes
// the response (spec §requests-and-responses).
func Handler(route string, h HandlerFunc, eh ErrorHandler, perform Performer, opts ...HandlerOption) http.Handler {
	if eh == nil {
		eh = DefaultErrorHandler
	}
	var s shim
	for _, o := range opts {
		o(&s)
	}
	return http.HandlerFunc(func(w http.ResponseWriter, hr *http.Request) {
		ctx := hr.Context()
		if s.timeout > 0 {
			var cancel context.CancelFunc
			ctx, cancel = context.WithTimeout(ctx, s.timeout)
			defer cancel()
		}
		body, err := bodyRead(hr)
		req := RequestOf(hr, route, time.Now(), body, s.params...)
		var resp Response
		if err != nil {
			resp = eh(req, err)
		} else {
			resp = h(req)
		}
		resp = resolve(ctx, req, resp, eh, perform)
		if err := resp.write(w, hr, req); err != nil {
			slog.Error("volt: writing the response", "route", route, "err", err)
		}
	})
}

func bodyRead(hr *http.Request) ([]byte, error) {
	if hr.Body == nil || hr.Body == http.NoBody {
		return nil, nil
	}
	b, err := io.ReadAll(http.MaxBytesReader(nil, hr.Body, MaxBodyBytes))
	if err != nil {
		var tooBig *http.MaxBytesError
		if errors.As(err, &tooBig) {
			return nil, Error(http.StatusRequestEntityTooLarge, "request body over the limit")
		}
		return nil, Error(http.StatusBadRequest, "reading the body: "+err.Error())
	}
	return b, nil
}

// DefaultErrorHandler is the Problem ProblemOf finds for err, and for
// any other error a 500 that logs the error (spec §formats).
func DefaultErrorHandler(r Request, err error) Response {
	if p, ok := ProblemOf(err); ok {
		return Response{status: p.Status, body: problemBody{p}}
	}
	slog.Error("volt: handler error", "route", r.Route(), "err", err)
	return Reject(http.StatusInternalServerError, "internal server error")
}

// ProblemOf is the Problem the error spine writes for err (spec §formats):
// an HTTPError's own status and message; a refused write, a *rt.Invalid,
// as 409 when a unique field error is among its fields and 422 otherwise
// (spec §changesets); a query's row miss (rt.ErrNotFound) as 404; each
// with the details of an error that itemizes them. ok is false for any
// other error.
func ProblemOf(err error) (p Problem, ok bool) {
	var he HTTPError
	var inv *rt.Invalid
	switch {
	case errors.As(err, &he):
		p = Problem{Status: he.StatusCode(), Message: he.Error()}
	case errors.As(err, &inv):
		p = Problem{Status: http.StatusUnprocessableEntity, Message: inv.Error()}
		for _, f := range inv.Fields {
			if f.Check == "unique" {
				p.Status = http.StatusConflict
			}
		}
	case errors.Is(err, rt.ErrNotFound):
		return Problem{Status: http.StatusNotFound, Message: "not found"}, true
	default:
		return Problem{}, false
	}
	var d Detailer
	if errors.As(err, &d) {
		p.Details = d.Details()
	}
	return p, true
}

// Chain composes middleware around h: the first element is outermost,
// matching pipeline declaration order.
func Chain(h http.Handler, mw ...func(http.Handler) http.Handler) http.Handler {
	for i := len(mw) - 1; i >= 0; i-- {
		h = mw[i](h)
	}
	return h
}

type statusWriter struct {
	http.ResponseWriter
	status int
	wrote  bool
}

func (w *statusWriter) WriteHeader(code int) {
	if !w.wrote {
		w.wrote = true
		w.status = code
	}
	w.ResponseWriter.WriteHeader(code)
}

func (w *statusWriter) Write(b []byte) (int, error) {
	if !w.wrote {
		w.wrote = true
		w.status = http.StatusOK
	}
	return w.ResponseWriter.Write(b)
}

// Flush forwards http.Flusher. Flushing commits the response (the header
// goes out as 200 if not yet written).
func (w *statusWriter) Flush() {
	if f, ok := w.ResponseWriter.(http.Flusher); ok {
		if !w.wrote {
			w.wrote = true
			w.status = http.StatusOK
		}
		f.Flush()
	}
}

// Unwrap exposes the underlying writer to http.ResponseController.
func (w *statusWriter) Unwrap() http.ResponseWriter { return w.ResponseWriter }

// Route is one row of the generated route table (volt_routes.go).
type Route struct {
	Method     string // "" for the any-verb
	Pattern    string // ServeMux pattern
	Spelled    string // DSL spelling
	Controller string
	Action     string
	Query      string // "pkg.Method" for a query route (§query-routes); Controller and Action are then empty
	Helper     string // reverse-URL function name, "" when none
	Params     []RouteParam
}

// RouteParam describes one captured parameter of a table row.
type RouteParam struct {
	Name string
	Type string // int, string
	Wild bool
}
